// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Minimal shape we need off a Server row to resolve its game family. */
type ServerLike = {
  osTemplate?: { family?: string | null } | null;
  gamePlan?: { gameFamily?: string | null } | null;
};

/**
 * Resolve the game family for a server, preferring the game plan's family and
 * falling back to the OS template's family. Returns the family string ONLY if a
 * customization schema exists for it, else null.
 */
/**
 * Families whose settings the worker can actually WRITE to the game server.
 *
 * worker/game-config.ts throws a customer-facing "your settings are NOT in
 * effect" for anything outside this set unless ENABLE_REAL_GAMECFG is on — so
 * for the other 39 families the UI was accepting a save, saying "queued for
 * apply", and the job then failing. The set lives here so the page can TELL the
 * customer before they type, instead of after the job fails; the worker imports
 * the same constant, so the two cannot drift.
 */
// `dayz` deliberately absent: `applyDayZ` (worker/game-config.ts) is fully
// written — serverDZ.cfg is genuinely file-based, patched via
// `updateDayZConfig`, unit-tested against a real reference cfg file (see
// test/dayz-config.test.ts) — but has NOT been confirmed live against a
// running container, because no Steam account exists in this environment to
// boot one (see lib/dayz-steam.ts). Add "dayz" here only after that live
// verification actually happens, per applyDayZ's own comment.
export const REAL_APPLY_FAMILIES = new Set<string>(["palworld", "minecraft", "rust", "valheim", "bedrock", "projectzomboid"]);

/**
 * Families where only SOME fields reach the running game. A family listed here
 * is in REAL_APPLY_FAMILIES (so the job runs) but every field NOT in its set is
 * saved only; the settings page says so per field. Families absent from this
 * map apply every field.
 *
 * projectzomboid (2026-10-02): ADMIN_PASSWORD only — worker/zomboid-admin.ts.
 * The rest (PublicName, PVP, ... and ADMIN_USERNAME) live in generated files or
 * the already-created account and are not written.
 */
export const LIVE_APPLY_FIELDS: Record<string, ReadonlySet<string>> = {
  projectzomboid: new Set(["ADMIN_PASSWORD"]),
};

/** Whether changing `key` really reaches the running game server. */
export function fieldAppliesLive(family: string | null | undefined, key: string): boolean {
  if (!family) return false;
  const only = LIVE_APPLY_FIELDS[family];
  return only ? only.has(key) : canApplyConfig(family);
}

/** Whether a family's saved settings will really reach the game server. */
export function canApplyConfig(family: string | null | undefined): boolean {
  return !!family && (process.env.ENABLE_REAL_GAMECFG === "1" || REAL_APPLY_FAMILIES.has(family));
}

export function familyFor(server: ServerLike | null | undefined): string | null {
  if (!server) return null;
  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
  if (fam && GAME_CONFIG_SCHEMAS[fam]) return fam;
  return null;
}

/** The customization schema for a family, or null. */
export function schemaFor(family: string | null | undefined): FamilySchema | null {
  if (!family) return null;
  return GAME_CONFIG_SCHEMAS[family] ?? null;
}

/** True if `variant` is a valid variant id for `family`. */
export function isValidVariant(family: string, variant: string): boolean {
  const s = GAME_CONFIG_SCHEMAS[family];
  return !!s && s.variants.some((v) => v.id === variant);
}

/**
 * May this variant be CHOSEN now (new order, or a Settings switch)? A variant
 * flagged `unavailable` can still be kept by a server that already has it:
 * pass `current` (the server's stored variant) to allow that.
 */
export function isSelectableVariant(family: string, variant: string, current?: string | null): boolean {
  const v = GAME_CONFIG_SCHEMAS[family]?.variants.find((x) => x.id === variant);
  if (!v) return false;
  return !v.unavailable || variant === current;
}

export type ValidateResult =
  | { ok: true; values: Record<string, string | number | boolean> }
  | { ok: false; error: string };

/**
 * Validate & coerce a settings object against a family's field schema. Unknown
 * keys are dropped; missing keys fall back to the field default. Returns a clean,
 * fully-populated values object ready to persist to `Server.gameConfig`.
 */
export function validateConfig(
  family: string,
  values: Record<string, unknown> | null | undefined
): ValidateResult {
  const schema = GAME_CONFIG_SCHEMAS[family];
  if (!schema) return { ok: false, error: `Unknown game family "${family}".` };

  const input = values ?? {};
  const out: Record<string, string | number | boolean> = {};

  for (const field of schema.fields) {
    const raw = input[field.key];
    const provided = raw !== undefined && raw !== null;

    switch (field.type) {
      case "bool": {
        out[field.key] = provided ? raw === true || raw === "true" || raw === "on" : (field.default as boolean);
        break;
      }
      case "int": {
        let n = provided ? Number(raw) : (field.default as number);
        if (!Number.isFinite(n)) return { ok: false, error: `${field.label} must be a number.` };
        n = Math.trunc(n);
        if (field.min !== undefined && n < field.min)
          return { ok: false, error: `${field.label} must be at least ${field.min}.` };
        if (field.max !== undefined && n > field.max)
          return { ok: false, error: `${field.label} must be at most ${field.max}.` };
        out[field.key] = n;
        break;
      }
      case "enum": {
        const v = provided ? String(raw) : String(field.default);
        if (!field.options?.some((o) => o.value === v))
          return { ok: false, error: `Invalid value for ${field.label}.` };
        out[field.key] = v;
        break;
      }
      case "string": {
        const v = provided ? String(raw) : String(field.default);
        if (field.required && v.trim().length === 0) {
          return {
            ok: false,
            error: `${field.label} is required.${field.help ? ` ${field.help}` : ""}`,
          };
        }
        if (v.length > 256) return { ok: false, error: `${field.label} is too long (max 256 chars).` };
        {
          // Field rules (minLength / notInsideField) — shared with the wizard's inline checks.
          const ruleErr = fieldRuleError(field, v, schema.fields, { ...input, ...out });
          if (ruleErr) return { ok: false, error: ruleErr };
        }
        {
          // String-field pattern/length rules (e.g. Valheim SERVER_NAME).
          const nameErr = stringFieldError(field, v);
          if (nameErr) return { ok: false, error: nameErr };
        }
        // CONFIG INJECTION: these values are written verbatim into LINE-ORIENTED
        // files on the customer's VM by worker/game-config.ts —
        // `server.properties` (`motd=<value>`), Rust's `server.cfg`
        // (`server.hostname "<value>"`) and Valheim's launch-args file. A newline
        // therefore does not set one option, it appends arbitrary further
        // options: a motd of "hi\nenable-rcon=true\nrcon.password=x" turns RCON
        // on with a chosen password, and that password is then read back out of
        // the same file and interpolated into an `mcrcon` command line.
        // `enum`/`int`/`bool` are constrained by their own branches; `string` was
        // the only field type with no allowlist at all, so it is checked here —
        // at the one point every caller (UI, server action and worker re-validation)
        // already goes through.
        // eslint-disable-next-line no-control-regex
        if (/[\x00-\x1f\x7f]/.test(v)) {
          return {
            ok: false,
            error: `${field.label} may not contain line breaks or control characters.`,
          };
        }
        out[field.key] = v;
        break;
      }
    }
  }

  return { ok: true, values: out };
}
