/**
 * GAME_REINSTALL — Danger Zone "Wipe & reinstall this game". Re-provisions the
 * GAME ONLY against the SAME, already-existing VM:
 *
 *   1. stop the game's systemd unit and `docker rm -f` its container
 *   2. wipe the CONTENTS of the game's own bind-mounted data directory(ies) —
 *      parsed straight from the family's real setupScript `-v host:container`
 *      flags (`dockerHostMountsFrom`, worker/game-variant.ts) — never a
 *      guessed path, same provenance discipline as lib/games.ts's
 *      GAME_JOIN_PORT_OVERRIDE/GAME_EXTRA_JOIN_PORTS
 *   3. re-run a FRESH build of the setup script (`buildGameSetupScript`),
 *      which reapplies the customer's CURRENT gameVariant/gameConfig — so a
 *      setting that silently never applied (see docs/DOCUMENTATION.md — only
 *      5 of 42 families apply saved settings today) gets a real chance to
 *      take effect on the fresh install — and mints brand-new per-server
 *      secrets for palworld/rust/cs2, the same "rotate, don't keep the old
 *      ones" rule `reinstall()`'s own comment (worker/index.ts) applies to
 *      the VPS root password.
 *
 * Never touches the VPS/VM itself: no Proxmox call, no vmid change, no
 * destroy/reclone, no IP/SSH-host-key change — this is exactly what the
 * Danger Zone subtitle promises ("Reinstall, wipe or cancel") that nothing
 * previously implemented. The VM must already be RUNNING (this runs entirely
 * over SSH into the live guest; unlike the VPS-level REINSTALL, there is no
 * Proxmox path that works on a stopped VM).
 *
 * Full "change game" (swap to a different family) is NOT implemented here —
 * that needs a different OsTemplate/GamePlan, different ports (see
 * lib/games.ts), possibly a different RCON setup, and a real disk-footprint
 * check, which is real, separable infrastructure work. Shipping wipe+
 * reinstall-SAME-game now rather than a half-built family-swap is the
 * deliberate scope line the task that produced this drew; the dashboard copy
 * must say "Reinstall (same game)" and note full game-swap as a documented
 * follow-up, not silently imply it does more than it does.
 */
export async function gameReinstall(job: Job): Promise<void> {
