 * Bake a customer's settings into the provisioning script so a fresh install
 * and a "Wipe & reinstall" come up already configured (the worker applier only
 * runs on Settings saves). Pure string rewrite of lib/terraria-plugins.ts's
 * TERRARIA_SETUP_SCRIPT; returns the script unchanged if it is not that shape.
 */
export function applyTerrariaSetup(setupScript: string, values: V | null | undefined): string {
  if (!values) return setupScript;
  const re = /-e WORLD_FILENAME=\S+ (.*?)ryshe\/terraria:latest (.*)$/s;
  const m = re.exec(setupScript);
  if (!m) return setupScript;
  const spec = terrariaWorldSpec(values);
  const q = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`;
  const args = terrariaCmdForWorld(m[2].trim().split(/\s+/), spec);
  const quoted = args.map((a, i) => (/^-(worldname|seed)$/.test(args[i - 1] ?? "") ? q(a) : a)).join(" ");
  let out = setupScript.replace(re, () => `-e WORLD_FILENAME=${terrariaWorldFile(spec)} ${m[1]}ryshe/terraria:latest ${quoted}`);
  // Seed TShock's config.json BEFORE first boot. TShock fills every key we leave out with its
  // default and rewrites the file (FileTools.LoadConfigAndCheckForChanges), so a partial file is safe.
  const json = JSON.stringify({ Settings: terrariaTshockSettings(values) });
  const seed = `mkdir -p ${TERRARIA_WORLD_DIR} && { [ -f ${TERRARIA_CONFIG_JSON} ] || printf '%s' ${q(json)} > ${TERRARIA_CONFIG_JSON}; } && `;
  out = out.replace("docker run -d --name terraria", () => `${seed}docker run -d --name terraria`);
  return out;
}

