  const eol = content.includes("\r\n") ? "\r\n" : "\n";
  const sep = opts.sep ?? "=";
  const norm = (s: string) => (opts.caseSensitive === false ? s.toLowerCase() : s);
  const lines = content.length ? content.split(/\r?\n/) : [];
  if (lines.length && lines[lines.length - 1] === "") lines.pop();
  const done = new Set<number>();

  edits.forEach((e, idx) => {
    const sec = e.section ?? "";
    let cur = "";
    let secStart = sec === "" ? 0 : -1;
    let lastInSec = sec === "" ? -1 : -1;
    for (let i = 0; i < lines.length; i++) {
      const s = sectionOf(lines[i]);
      if (s !== null) {
        cur = s;
        if (norm(cur) === norm(sec) && secStart < 0) { secStart = i; lastInSec = i; }
        continue;
      }
      if (norm(cur) !== norm(sec)) continue;
      if (!isComment(lines[i]) && lines[i].trim() !== "") lastInSec = i;
      if (isComment(lines[i])) continue;
      const eq = lines[i].indexOf("=");
      const colon = opts.sep === ":" ? lines[i].indexOf(":") : -1;
      const at = colon >= 0 ? colon : eq;
      if (at < 0) continue;
      if (norm(lines[i].slice(0, at).trim()) === norm(e.key)) {
        lines[i] = `${lines[i].slice(0, at).replace(/\s+$/, "")}${sep}${e.value}`;
        done.add(idx);
        return;
      }
    }
    // not found: append
    if (sec === "") {
      // before the first section header, after the last top-level key
      let at = lines.findIndex((l) => sectionOf(l) !== null);
      if (at < 0) at = lines.length;
      lines.splice(at, 0, `${e.key}${sep}${e.value}`);
    } else if (secStart >= 0) {
      lines.splice((lastInSec < 0 ? secStart : lastInSec) + 1, 0, `${e.key}${sep}${e.value}`);
    } else {
      if (lines.length && lines[lines.length - 1].trim() !== "") lines.push("");
      lines.push(`[${sec}]`, `${e.key}${sep}${e.value}`);
    }
  });
  return lines.join(eol) + eol;
}

/** Read one value; undefined if absent. */
export function readIni(content: string, section: string, key: string, caseSensitive = true): string | undefined {
  const norm = (s: string) => (caseSensitive ? s : s.toLowerCase());
  let cur = "";
  for (const l of content.split(/\r?\n/)) {
    const s = sectionOf(l);
    if (s !== null) { cur = s; continue; }
    if (isComment(l) || norm(cur) !== norm(section)) continue;
    const eq = l.indexOf("=");
    if (eq >= 0 && norm(l.slice(0, eq).trim()) === norm(key)) return l.slice(eq + 1).trim();
  }
  return undefined;
}
