  const carried = [...wantEnv].filter(([k, v]) => imgEnv.get(k) !== v);
  const envText = carried.map(([k, v]) => `${k}=${v.replace(/\r?\n/g, " ")}`).join("\n") + (carried.length ? "\n" : "");
  const entryOverridden = !!cur.entrypoint && imgEntry !== undefined && JSON.stringify(cur.entrypoint) !== JSON.stringify(imgEntry);
  const cmdArgs = [...(entryOverridden ? cur.entrypoint!.slice(1) : []), ...wantCmd];
  const create = [
    `docker create --name ${shq(c)}`,
    ...Object.entries(cur.logOpts).map(([k, v]) => `--log-opt ${shq(`${k}=${v}`)}`),
    cur.user ? `--user ${shq(cur.user)}` : "",
    ...cur.ports.map((p) => `-p ${shq(p)}`),
    ...cur.binds.map((b) => `-v ${shq(b)}`),
    `--env-file ${shq(o.envFile)}`,
    entryOverridden ? `--entrypoint ${shq(cur.entrypoint![0])}` : "",
    shq(cur.image),
    ...cmdArgs.map(shq),
  ].filter(Boolean).join(" ");

